# name: prior_four_obj_three_duplicate_singleton
# description: On 4-object prior trials containing a unique singleton alongside three identical duplicate distractors, the mean points allocated to the singleton object.
def test_statistic(df):
    table = {}
    distinct = df[["objects", "heard"]].drop_duplicates()
    for _, sc in distinct.iterrows():
        if not pd.isna(sc["heard"]):
            continue
        objs = json.loads(sc["objects"])
        if len(objs) == 4:
            counts = {tuple(o): objs.count(o) for o in objs}
            if sorted(counts.values()) == [1, 3]:
                s_idx = [i for i, o in enumerate(objs) if counts[tuple(o)] == 1][0]
                table[sc["objects"]] = s_idx
    pts_list = [json.loads(p) if isinstance(p, str) else p for p in df["points"]]
    total, count = 0.0, 0
    for idx, (h, p) in enumerate(zip(df["heard"], pts_list)):
        if not pd.isna(h):
            continue
        key = df["objects"].iloc[idx]
        if key in table:
            total += p[table[key]]
            count += 1
    return float(total / max(count, 1))

# name: prior_competing_sparse_minus_dense
# description: On prior trials with duplicate 0-feature distractors and two singletons (sparse 1-feature vs dense all-features), the mean points allocated to the sparse singleton minus the dense singleton.
def test_statistic(df):
    table = {}
    distinct = df[["objects", "heard"]].drop_duplicates()
    for _, sc in distinct.iterrows():
        if not pd.isna(sc["heard"]):
            continue
        objs = json.loads(sc["objects"])
        counts = {tuple(o): objs.count(o) for o in objs}
        singletons = [i for i, o in enumerate(objs) if counts[tuple(o)] == 1]
        duplicates = [i for i, o in enumerate(objs) if counts[tuple(o)] > 1]
        if len(singletons) == 2 and duplicates and all(sum(objs[i]) == 0 for i in duplicates):
            fc = [sum(objs[i]) for i in singletons]
            s_idx = singletons[int(np.argmin(fc))]
            d_idx = singletons[int(np.argmax(fc))]
            table[sc["objects"]] = (s_idx, d_idx)
    pts_list = [json.loads(p) if isinstance(p, str) else p for p in df["points"]]
    total, count = 0.0, 0
    for idx, (h, p) in enumerate(zip(df["heard"], pts_list)):
        if not pd.isna(h):
            continue
        key = df["objects"].iloc[idx]
        if key in table:
            s_idx, d_idx = table[key]
            total += (p[s_idx] - p[d_idx])
            count += 1
    return float(total / max(count, 1))

# name: complex_competitor_minus_distractor_gap
# description: On communicative trials with both a feature-rich competitor (true of the heard message) and a feature-rich distractor (false of the heard message), the mean point difference between the competitor and the distractor.
def test_statistic(df):
    table = {}
    distinct = df[["objects", "heard"]].drop_duplicates()
    for _, sc in distinct.iterrows():
        if pd.isna(sc["heard"]):
            continue
        h = int(sc["heard"])
        objs = json.loads(sc["objects"])
        sat = [i for i, o in enumerate(objs) if o[h] == 1]
        unsat = [i for i, o in enumerate(objs) if o[h] == 0]
        fc = [sum(o) for o in objs]
        min_c = min(fc[i] for i in sat)
        comp_complex = [i for i in sat if fc[i] >= 3 and fc[i] > min_c]
        dist_complex = [i for i in unsat if fc[i] >= 3]
        if comp_complex and dist_complex:
            table[(sc["objects"], h)] = (comp_complex[0], dist_complex)
    pts_list = [json.loads(p) if isinstance(p, str) else p for p in df["points"]]
    total, count = 0.0, 0
    for idx, (h, p) in enumerate(zip(df["heard"], pts_list)):
        if pd.isna(h):
            continue
        key = (df["objects"].iloc[idx], int(h))
        if key in table:
            c_idx, d_indices = table[key]
            d_mean = sum(p[i] for i in d_indices) / len(d_indices)
            total += (p[c_idx] - d_mean)
            count += 1
    return float(total / max(count, 1))

# name: three_object_scalar_competitor_points
# description: On 3-object communicative trials with a unique minimal target and an uninformative competitor satisfying the message, the mean points allocated to the competitor object.
def test_statistic(df):
    table = {}
    distinct = df[["objects", "heard"]].drop_duplicates()
    for _, sc in distinct.iterrows():
        if pd.isna(sc["heard"]):
            continue
        h = int(sc["heard"])
        objs = json.loads(sc["objects"])
        if len(objs) == 3:
            sat = [i for i, o in enumerate(objs) if o[h] == 1]
            if len(sat) > 1:
                fc = [sum(objs[i]) for i in sat]
                min_c = min(fc)
                if fc.count(min_c) == 1:
                    target_idx = sat[fc.index(min_c)]
                    comp_indices = [i for i in sat if i != target_idx]
                    table[(sc["objects"], h)] = comp_indices
    pts_list = [json.loads(p) if isinstance(p, str) else p for p in df["points"]]
    total, count = 0.0, 0
    for idx, (h, p) in enumerate(zip(df["heard"], pts_list)):
        if pd.isna(h):
            continue
        key = (df["objects"].iloc[idx], int(h))
        if key in table:
            total += sum(p[i] for i in table[key]) / len(table[key])
            count += 1
    return float(total / max(count, 1))

